// Build-along projects: guided mini projects beyond the Book (docs/FEATURES_BRIEF.md, agent 4).
// The data comes from scripts/buildalong/ (see data.ts, generated by scripts/buildalong/build.mjs).
import type { SectionId } from '../../content/types';

export type BuildAlongMilestone = {
  /** "m3" */
  id: string;
  title: string;
  /** What to build, with `backtick` code (render with Rich). */
  build: string;
  /** Book section that helps. */
  section: SectionId;
  /** Files worth opening for this milestone, relative to the project root. */
  files: string[];
  /** `cargo test --test milestones <filter>`: "m3_". */
  filter: string;
  /** Test function names in tests/milestones.rs that belong to this milestone. */
  tests: string[];
};

export type BuildAlongProject = {
  /** Folder and crate name: ~/projects/<name>. */
  name: 'todo' | 'mdhtml' | 'wordfreq' | 'bank' | 'life' | (string & {});
  title: string;
  summary: string;
  /** Book section to have read first. */
  after: SectionId;
  /** Command that runs the finished program. */
  run: string;
  /** The milestone tests file, restored before each check. */
  testFile: string;
  /** Every file the project starts with (Cargo.toml, starter code, tests), relative to its root. */
  files: Record<string, string>;
  milestones: BuildAlongMilestone[];
};
